#include "whj2/profile.hpp"
#include "image.hpp"
#include "model.hpp"
extern "C" {
#include "video.h"
}
#include <iostream>
#include <algorithm>
static size_t images=0,pixels=0,audio=0,samples=0,containers=0,videos=0,frames=0,models=0,vertices=0,faces=0;
static void check(const qlie::Bytes&b,const std::string&name,unsigned depth=0){if(depth>20)throw std::runtime_error("Composite nesting overflow");if(b.empty())return;if(b.size()>12&&std::equal(b.begin(),b.begin()+12,"ARGBModel1.0")){auto m=whj2::model(b);models++;for(auto&o:m.objects){vertices+=o.vertices.size();faces+=o.faces.size();}return;}if(b.size()<4)throw std::runtime_error("Truncated media payload "+name);if(b.size()>5&&std::equal(b.begin(),b.begin()+5,"abmp1")){containers++;for(auto&m:whj2::abmp(b))if(m.type.rfind("abimg",0)==0||m.type.rfind("absnd",0)==0)check(m.data,name+"#"+m.name,depth+1);return;}if((b[0]==137&&b[1]==80)||(b[0]==255&&b[1]==216)||std::equal(b.begin(),b.begin()+4,"DPNG")){auto im=whj2::image(b);images++;pixels+=size_t(im.width)*im.height;return;}if(std::equal(b.begin(),b.begin()+4,"OggS")||std::equal(b.begin(),b.begin()+4,"RIFF")){bool movie=name.find(".ogv")!=name.npos||std::search(b.begin(),b.begin()+std::min<size_t>(b.size(),4096),"theora",&"theora"[6])!=b.begin()+std::min<size_t>(b.size(),4096);if(movie){KVideo*v=kvideo_open_mode(b.data(),b.size(),KVIDEO_SOFTWARE);if(!v)throw std::runtime_error("Video open failed "+name);qlie::Bytes pixels(1280*720*4);KImage dst{0,0,1280,720,1280*4,pixels.data()};int rc=0;unsigned tick=0;for(;tick<108000;tick++){uint8_t*pcm=nullptr;size_t count=0;rc=kvideo_step(v,&dst,&pcm,&count);samples+=count/4;free(pcm);if(rc)break;}frames+=kvideo_decoded_frames(v);if(rc<0){std::string error=kvideo_error(v);kvideo_close(v);throw std::runtime_error(error);}if(!rc){kvideo_close(v);throw std::runtime_error("Video did not reach EOF "+name);}std::cout<<"video "<<name<<" frames="<<kvideo_decoded_frames(v)<<" ticks="<<tick<<" EOF\n";kvideo_close(v);videos++;return;}uint8_t*p=nullptr;size_t n=0;if(kaudio_decode(b.data(),b.size(),&p,&n))throw std::runtime_error("Audio decoding failed "+name);audio++;samples+=n/4;free(p);return;}throw std::runtime_error("Unexpected composite payload "+name);}
int main(int argc,char**argv){try{if(argc<2)throw std::runtime_error("usage: media-probe GAME");qlie::Assets a(argv[1],whj2::profile::archives);size_t n=0;for(const auto&name:a.names()){auto at=name.rfind(46);auto ext=name.substr(at==name.npos?name.size():at);if(ext!=".png"&&ext!=".b"&&ext!=".ogg"&&ext!=".wav"&&ext!=".ogv")continue;try{check(a.read(name),name);}catch(const std::exception&e){throw std::runtime_error(name+": "+e.what());}if(++n%200==0)std::cout<<n<<" media resources decoded\n";}std::cout<<"PASS images="<<images<<" pixels="<<pixels<<" audio="<<audio<<" stereo_samples="<<samples<<" videos="<<videos<<" frames="<<frames<<" models="<<models<<" model_vertices="<<vertices<<" model_faces="<<faces<<" composite_containers="<<containers<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
